// Testbench (T15e): ft710_uart_rx (behavioural) against the structural netlist slice of UART A.
//
// Without STRUCT it only runs the behavioural model (no derived files needed).
// With -DSTRUCT it also instantiates `ft710_slice` from build/sdr/sim/uart_a_rx.v, generated by
//   python3 -I tools/xc7_netlist_verilog.py slice build/sdr/netlist.json build/sdr/sim/uart_a_rx.v \
//     --seeds SLICE_X1Y92/AFF,SLICE_X1Y93/AFF,SLICE_X1Y93/B5FF,SLICE_X1Y93/BFF,SLICE_X1Y93/CFF,SLICE_X1Y93/DFF,SLICE_X2Y93/AFF,SLICE_X2Y93/BFF,SLICE_X2Y93/CFF --depth 4
// and compares byte register and strobe on every clock. See hdl/sdr/README.md for the command lines.

`timescale 1ns/1ps
`default_nettype none
module tb_uart_rx;
  reg clk = 1'b0;
  always #4 clk = ~clk;                     // 125 MHz
  reg rst = 1'b1;
  reg rx = 1'b1;
  real bit_ns = 1.0e9 / 115200.0;
  real skew = 1.0;                          // baud error of the sender (1.0 = exact)

  wire [7:0] data;
  wire valid;
  ft710_uart_rx dut (.clk(clk), .rst(rst), .rx(rx), .data(data), .valid(valid));

  integer errors = 0, bytes = 0, k;
  reg [7:0] expect_q [0:63];
  integer head = 0, tail = 0;

`ifdef STRUCT
  wire [7:0] sdata;
  wire svalid;
  ft710_slice s (
    .i_BUFHCE_X0Y22_O(clk), .i_IOB_X0Y41_I(rx),
    .i_SLICE_X11Y59_BLUT_O(1'b0), .i_SLICE_X41Y70_B5FF_Q(1'b0), .i_SLICE_X2Y52_AFF_Q(1'b0),
    .i_SLICE_X3Y93_CLUT_O(1'b0), .i_SLICE_X1Y93_CLUT_O(1'b0), .i_SLICE_X31Y67_C5FF_Q(1'b0),
    .i_SLICE_X33Y73_AFF_Q(1'b0), .i_SLICE_X32Y73_AFF_Q(1'b0),
    .o_SLICE_X1Y92_AFF_Q(svalid),
    .o_SLICE_X2Y93_AFF_Q(sdata[0]), .o_SLICE_X1Y93_AFF_Q(sdata[1]), .o_SLICE_X1Y93_BFF_Q(sdata[2]),
    .o_SLICE_X1Y93_CFF_Q(sdata[3]), .o_SLICE_X1Y93_DFF_Q(sdata[4]), .o_SLICE_X2Y93_BFF_Q(sdata[5]),
    .o_SLICE_X1Y93_B5FF_Q(sdata[6]), .o_SLICE_X2Y93_CFF_Q(sdata[7]));
  // the slice's global reset flip-flop is released by logic outside the slice: drive it from rst
  always @(*) force s.w_SLICE_X10Y76_BFF_Q = rst;
  integer cycles = 0, mism = 0;
  always @(posedge clk) if (!rst) begin
    cycles = cycles + 1;
    if (svalid !== valid || (valid && sdata !== data)) begin
      mism = mism + 1;
      if (mism < 10) $display("%t MISMATCH rtl valid=%b data=%02x  netlist valid=%b data=%02x",
                              $time, valid, data, svalid, sdata);
    end
  end
`endif

  task send(input [7:0] b);
    begin
      expect_q[head] = b; head = head + 1;
      rx = 1'b0; #(bit_ns * skew);
      for (k = 0; k < 8; k = k + 1) begin rx = b[k]; #(bit_ns * skew); end
      rx = 1'b1; #(bit_ns * skew);
    end
  endtask

  reg last_valid = 1'b0;
  always @(posedge clk) begin
    if (valid && !last_valid) begin
      bytes = bytes + 1;
      if (data !== expect_q[tail]) begin
        errors = errors + 1;
        $display("%t RX got %02x expected %02x", $time, data, expect_q[tail]);
      end
      tail = tail + 1;
    end
    last_valid <= valid;
  end

  initial begin
    #1000 rst = 1'b0;
    #(5 * bit_ns);
    // MAIN's read frame for register 0x0000, then a write frame, then edge cases
    send("r"); send("0"); send("0"); send("0"); send("0"); send("3"); send("2"); send(8'h0D);
    send("w"); send("0"); send("0"); send("3"); send("7"); send("B"); send("C"); send("C"); send("5");
    send(8'h00); send(8'hFF); send(8'h55); send(8'hAA);
    skew = 1.02;  send(8'hA5);              // sender 2 % slow
    skew = 0.98;  send(8'h5A);              // sender 2 % fast
    skew = 1.0;
    #(5 * bit_ns);
    $display("bytes %0d, errors %0d", bytes, errors);
`ifdef STRUCT
    $display("netlist comparison: %0d clocks, %0d mismatches", cycles, mism);
    if (mism) errors = errors + mism;
`endif
    if (errors == 0 && bytes == head) $display("PASS");
    else $display("FAIL");
    $finish;
  end
endmodule
`default_nettype wire
